/**
 * RFP data-universe branch — A = internal, B = external/public, E = SSoT-generated output
 */
export type CorpusDocumentCategory = typeof CorpusDocumentCategory[keyof typeof CorpusDocumentCategory];


export const CorpusDocumentCategory = {
  A: 'A',
  B: 'B',
  E: 'E',
} as const;

export type IngestFilterSentiment = typeof IngestFilterSentiment[keyof typeof IngestFilterSentiment];


export const IngestFilterSentiment = {
  positive: 'positive',
  negative: 'negative',
  mixed: 'mixed',
  neutral: 'neutral',
} as const;

/**
 * Filter-before-ingest provenance for external sources (keywords / competitors / executives / topics, with a +/- mention flag)
 */
export interface IngestFilter {
  keywords: string[];
  competitors: string[];
  executives: string[];
  topics: string[];
  sentiment: IngestFilterSentiment;
}

export interface CorpusDocument {
  id: string;
  /** RFP data-universe branch — A = internal, B = external/public, E = SSoT-generated output */
  category: CorpusDocumentCategory;
  title: string;
  country: string;
  brand: string;
  entity: string;
  quarter: string;
  type: string;
  confidentiality: string;
  owner: string;
  validity: string;
  /** @nullable */
  validUntil?: string | null;
  language: string;
  topics: string[];
  axisIds: string[];
  summary: string;
  chunkCount: number;
  /** Simulated source format (structured Word, Excel numeric, PDF, self-explanatory PPT, API feed, manual form, SharePoint dump) */
  sourceFormat: string;
  /** Simulated connector / provenance the document arrived through */
  connector: string;
  /**
     * ISO timestamp of when the document actually entered the corpus (live uploads and feed items); seed documents omit it
     * @nullable
     */
  addedAt?: string | null;
  /**
     * Refresh cadence of the source (quarterly, ~48h, near-real-time, ad hoc...)
     * @nullable
     */
  frequency?: string | null;
  /**
     * Version label for versioned material (mostly SSoT-generated outputs)
     * @nullable
     */
  version?: string | null;
  /** Present only on external docs — what the pre-ingest filter matched */
  ingestFilter?: IngestFilter | null;
  /**
     * Id of the older document this version replaces (version lineage)
     * @nullable
     */
  supersedes?: string | null;
  /**
     * Id of the newer document that replaces this one (derived)
     * @nullable
     */
  supersededBy?: string | null;
  /** For SSoT-generated docs — the governed source docs this output was generated from */
  lineageSourceDocIds?: string[];
}

