export interface GenerateInput {
  /** messaging | press | multiformat | visualdeck */
  shape: string;
  /** @minLength 1 */
  topic: string;
  /** Active persona id (drives clearance) */
  roleId: string;
  /** internal | external */
  audience: string;
  /**
     * Optional brand template chosen in the Generate tab. When present and valid it drives the section blueprint, required disclaimers and default export template.
     * @nullable
     */
  templateId?: string | null;
  /** BCP-47-ish code, e.g. en, es */
  language?: string;
  /** Destination confidentiality of the document */
  confidentiality?: string;
  /** Output format hint, e.g. document, email, note */
  format?: string;
  axisIds?: string[];
  /**
     * Named spokesperson for quotes and spokesperson notes
     * @nullable
     */
  spokesperson?: string | null;
  /**
     * Event or publication date framing the document
     * @nullable
     */
  eventDate?: string | null;
  /** Structured KPI panel context handed over from the KPIs page. Carries the active filters only — the engine recomputes every figure server-side under the persona's clearance (fail closed) before any of it reaches the composer. */
  kpiContext?: null | KpiReportContext;
  /** Structured Ask answer handoff from the Ask page. Carries the original question, the cited document ids and honest status flags only — never snippets or answer text. The engine re-derives every cited source's accessibility server-side under the CURRENT persona's clearance and the destination gate (fail closed), so a tampered or stale payload can never surface content the persona could not retrieve itself. */
  askContext?: null | AskHandoffContext;
  /** User-provided brief attachments (pasted brief/data and governed source links). Passed to the composer as clearly labeled user-provided context only — never treated as governed evidence, never cited, and never folded into retrieval. */
  attachments?: null | BriefAttachments;
  /**
     * Optional visual-deck layout selection. When present and non-empty the slide composer builds the deck from these pool layouts only (the cover and closing layouts stay available so the deck frame is never broken). Ids must come from GET /generate/visual-layouts; unknown ids are rejected with 400. Ignored for non-visualdeck shapes.
     * @nullable
     */
  layoutIds?: string[] | null;
  /**
     * Visual-deck target length: standard (~12-16 slides, single-pass), extended (~25-35 slides) or full (~40-60 slides). Extended and full run a chaptered multi-pass composition with per-chapter governed retrieval; the deck honestly shrinks when the permitted corpus cannot support the requested length. Ignored for non-visualdeck shapes. Absent = standard.
     * @nullable
     */
  deckLength?: string | null;
}

